import React, { useState, useEffect, useCallback } from 'react';
import './App.css';
import { emailApi, Email, Account, SearchParams } from './services/api';

function App() {
  const [emails, setEmails] = useState<Email[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [selectedEmail, setSelectedEmail] = useState<Email | null>(null);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<any>(null);

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedAccount, setSelectedAccount] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');

  const categories = [
    'All',
    'Interested',
    'Meeting Booked',
    'Not Interested',
    'Spam',
    'Out of Office',
    'Uncategorized'
  ];

  // Loader functions wrapped with useCallback
  const loadAccounts = useCallback(async () => {
    try {
      const data = await emailApi.getAccounts();
      setAccounts(data);
    } catch (error) {
      console.error('Failed to load accounts:', error);
    }
  }, []);

  const loadStats = useCallback(async () => {
    try {
      const data = await emailApi.getStats();
      setStats(data);
    } catch (error) {
      console.error('Failed to load stats:', error);
    }
  }, []);

  const loadEmails = useCallback(async () => {
    setLoading(true);
    try {
      const params: SearchParams = { limit: 50 };
      if (searchQuery) params.query = searchQuery;
      if (selectedAccount) params.accountId = selectedAccount;
      if (selectedCategory && selectedCategory !== 'All') {
        params.category = selectedCategory;
      }

      const result = await emailApi.search(params);
      setEmails(result.emails);
    } catch (error) {
      console.error('Failed to load emails:', error);
    } finally {
      setLoading(false);
    }
  }, [searchQuery, selectedAccount, selectedCategory]);

  // useEffect with proper dependencies
  useEffect(() => {
    loadAccounts();
    loadStats();
    loadEmails();
  }, [loadAccounts, loadStats, loadEmails]);

  const handleSearch = () => {
    loadEmails();
  };

  const getCategoryColor = (category: string) => {
    const colors: any = {
      'Interested': '#10b981',
      'Meeting Booked': '#3b82f6',
      'Not Interested': '#ef4444',
      'Spam': '#f59e0b',
      'Out of Office': '#8b5cf6',
      'Uncategorized': '#6b7280'
    };
    return colors[category] || '#6b7280';
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString();
  };

  // ... rest of your JSX code remains the same
}

export default App;
